package main

import (
	"database/sql"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// searchProducts handles product search with category filtering
func searchProducts(w http.ResponseWriter, r *http.Request) {
	category := r.URL.Query().Get("category")
	minPrice := r.URL.Query().Get("min_price")
	sortField := r.URL.Query().Get("sort")

	if category == "" {
		http.Error(w, "category required", http.StatusBadRequest)
		return
	}

	// Build query with parameterized price but dynamic category filter
	// Category is expected to be a slug like "electronics" or "home-garden"
	var query string
	if sortField != "" {
		// Allow sorting by predefined fields
		allowedSorts := map[string]bool{"price": true, "name": true, "created_at": true}
		if !allowedSorts[sortField] {
			sortField = "created_at"
		}
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' AND price >= $1 ORDER BY %s LIMIT 50",
			category, sortField,
		)
	} else {
		query = fmt.Sprintf(
			"SELECT id, name, price, description FROM products WHERE category = '%s' AND price >= $1 LIMIT 50",
			category,
		)
	}

	rows, err := db.Query(query, minPrice)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "internal error", http.StatusInternalServerError)
		return
	}
	defer rows.Close()

	w.Header().Set("Content-Type", "application/json")
	w.Write([]byte("["))
	first := true
	for rows.Next() {
		var id int
		var name, description string
		var price float64
		if err := rows.Scan(&id, &name, &price, &description); err != nil {
			continue
		}
		if !first {
			w.Write([]byte(","))
		}
		// Manual JSON construction - potential injection but not the main vuln
		jsonItem := fmt.Sprintf(
			`{"id":%d,"name":"%s","price":%.2f,"description":"%s"}`,
			id, strings.ReplaceAll(name, `"`, `\"`), price, strings.ReplaceAll(description, `"`, `\"`))
		w.Write([]byte(jsonItem))
		first = false
	}
	w.Write([]byte("]"))
}

// getProductDetail returns a single product
func getProductDetail(w http.ResponseWriter, r *http.Request) {
	productID := r.URL.Query().Get("id")
	if productID == "" {
		http.Error(w, "id required", http.StatusBadRequest)
		return
	}
	// This one is properly parameterized
	row := db.QueryRow("SELECT id, name, price, description, category FROM products WHERE id = $1", productID)
	var id int
	var name, description, cat string
	var price float64
	if err := row.Scan(&id, &name, &price, &description, &cat); err != nil {
		http.Error(w, "not found", http.StatusNotFound)
		return
	}
	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"id":%d,"name":"%s","price":%.2f,"description":"%s","category":"%s"}`,
		id, strings.ReplaceAll(name, `"`, `\"`), price,
		strings.ReplaceAll(description, `"`, `\"`),
		strings.ReplaceAll(cat, `"`, `\"`))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/api/products/detail", getProductDetail)
	log.Println("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
